{"explanation":"Tracks enabled eligibility, per-group requirement mode, and one open panel per group. It initializes required groups from fixed panel order, applies each event independently, removes ineligible panels, refills required groups, and derives the exact open, expanded, and sorted unsatisfied output.","program":"function solve({config,state,event}){
const G=config.groups,P=config.panels;
let s=state;
const gi=id=>{for(let i=0;i<G.length;i++)if(G[i].id===id)return i;return -1};
const pi=id=>{for(let i=0;i<P.length;i++)if(P[i].id===id)return i;return -1};
if(s===null){s={e:P.map(p=>p.enabled),o:G.map(()=>null),r:G.map(g=>g.required)};for(let i=0;i<G.length;i++)if(s.r[i])for(let j=0;j<P.length;j++)if(P[j].group===G[i].id&&s.e[j]){s.o[i]=P[j].id;break}}
if(event.type==='toggle'){let j=pi(event.id);if(j>=0&&s.e[j]){let i=gi(P[j].group);if(s.o[i]===P[j].id){if(!s.r[i])s.o[i]=null}else s.o[i]=P[j].id}}
else if(event.type==='enabled'){let j=pi(event.id);if(j>=0)s.e[j]=event.value}
else if(event.type==='close'){let i=gi(event.group);if(i>=0&&!s.r[i])s.o[i]=null}
else if(event.type==='mode'){let i=gi(event.group);if(i>=0)s.r[i]=event.required}
for(let i=0;i<G.length;i++){let j=pi(s.o[i]);if(j<0||!s.e[j])s.o[i]=null;if(s.o[i]===null&&s.r[i])for(let k=0;k<P.length;k++)if(P[k].group===G[i].id&&s.e[k]){s.o[i]=P[k].id;break}}
let open={},expanded=[];for(let i=0;i<G.length;i++)open[G[i].id]=s.o[i];for(let j=0;j<P.length;j++)for(let i=0;i<G.length;i++)if(s.o[i]===P[j].id)expanded.push(P[j].id);
let unsatisfied=[];for(let i=0;i<G.length;i++)if(s.r[i]&&s.o[i]===null)unsatisfied.push(G[i].id);unsatisfied.sort();
return{state:s,output:{open,expanded,unsatisfied}};
}"}
